package com.herbcraft.knowledge;
import com.google.gson.*; import com.herbcraft.Herbcraft; import java.io.*; import java.nio.charset.StandardCharsets; import java.util.*;
public final class KnowledgeRumorRegistry {
 private static final Map<String,List<KnowledgeClaim>> CLAIMS=new HashMap<>(); private KnowledgeRumorRegistry(){}
 public static void loadFromBundledJson(){ CLAIMS.clear(); try(InputStream in=KnowledgeRumorRegistry.class.getClassLoader().getResourceAsStream("data/herbcraft/knowledge_rumors.json")){ if(in==null)return; JsonObject root=JsonParser.parseReader(new InputStreamReader(in,StandardCharsets.UTF_8)).getAsJsonObject(); for(Map.Entry<String,JsonElement> e:root.entrySet()){ String key=e.getKey().contains("/")?e.getKey():"herbal/"+e.getKey().substring(e.getKey().lastIndexOf(':')+1); List<KnowledgeClaim> list=new ArrayList<>(); JsonObject obj=e.getValue().getAsJsonObject(); if(obj.has("claims")) for(JsonElement ce:obj.getAsJsonArray("claims")){ JsonObject c=ce.getAsJsonObject(); PageKind tier=PageKind.byName(c.has("source_tier")?c.get("source_tier").getAsString():"common"); boolean truth=c.has("truth")&&c.get("truth").getAsBoolean(); boolean suspicious=c.has("suspicious")?c.get("suspicious").getAsBoolean():!truth; list.add(new KnowledgeClaim(key,c.get("id").getAsString(),c.has("type")?c.get("type").getAsString():"note",c.get("text_key").getAsString(),truth,tier,suspicious)); } CLAIMS.put(key,List.copyOf(list)); }} catch(Exception ex){ Herbcraft.LOGGER.warn("Failed to load knowledge_rumors.json", ex); }}
 public static List<KnowledgeClaim> claims(String entryKey){ return CLAIMS.getOrDefault(entryKey,List.of()); }
 public static KnowledgeClaim claim(String entryKey,String claimId){ return claims(entryKey).stream().filter(c->c.id().equals(claimId)).findFirst().orElse(null); }
}
